 function scopeLabel(t){if(t.custom||t.edited||t.demo)return t.scope||'待确认范围';if(projectPhase!=='研发')return t.scope;if(route==='all')return t.stage==='S1'||t.stage==='S2'?'四路线 · 共用任务':'待确认的入选范围';if(['T11','T13','T14','T26','T61','T62'].includes(t.id))return route+'相关范围 · 保留共用条件';return route==='R3'&&['T12','T21','T22'].includes(t.id)?'R3 · 底层与面层':route+' · '+(t.stage>'S2'?'入选待确认':'适用范围')}
 function stageNote(){if(mode==='plan'&&data.draftRevision)return '本地关系已手动调整，前置与交付要求需结合节点详情重新核对。来源快照保留用于对照，修改不自动放行。';if(projectPhase!=='研发')return '连线展示当前阶段的任务工作顺序示例，具体依赖和审核要求待确认，不表示已执行或已放行。';return ({S1:'相关实施条件可用后，相容验证与清漆空白可并行；所有相关证据汇合后形成范围决定。',S2:'初始条件满足后，沸水与擦伤使用独立试板并行。比较入选仍需施工窗、初始、两项测试及匹配空白的完整证据。',S3:'仅承接实际入选的前2条路线和既有因子方案。当前未指定入选路线，不重算配方或重新设计 DOE。',S4:'承接已确认的化学方案与热预算；剔除窗口留档，2个长时候选的来源和版本须人工确认。',S5:'候选版本、签名暴露卡与样板证据齐备才入箱。短时检查点不能替代三批3000h及老化后界面确认。',S6:'客户矩阵准备可提前；正式准入仍要求 G4、完整客户证据与授权签核，不以内部筛选替代。'})[stage]}
