 function switchFlowConversation(id){if(id===flowConversationId||!flowConversationRows().some(row=>row.id===id))return;flowConversationDrafts[flowConversationId]=$('#rf-chat-input')?.value||projectDraft;flowConversations[flowConversationId]=chatMessages;flowConversationId=id;chatMessages=flowConversations[id]||(flowConversations[id]=[]);projectDraft=flowConversationDrafts[id]||'';attachments=[];render();$('#rf-chat-input')?.focus({preventScroll:true})}
