 function bindProjectWorkspaceSwitch(){page.querySelectorAll('[data-project-workspace-view]').forEach(button=>button.onclick=()=>{if(button.dataset.projectWorkspaceView==='flow')return;const activeId=v3Navigation.packageId||selected||ProjectStore?.active()?.currentNodeId,target=phaseViews[projectPhase]?.tasks.find(t=>t.id===activeId)||stageTasks().find(t=>taskStatus(t)==='进行中')||stageTasks()[0];if(!target)return toast('请先进入一个包含工作包的阶段');enterNodeWorkspace(target.id)})}
