 function workPackageDeliveries(t){try{const stored=JSON.parse(localStorage.getItem('synmat-task-workspaces')||'{}'),ws=stored[[projectPhase,substageName(t),t.name].join('/')],refs=ws?.taskCanvas?.deliverables;if(!Array.isArray(refs))return null;const assets=nodeAssetRecords(t);return refs.map(ref=>({...ref,...assets.find(a=>a.name===ref.name),name:ref.name,text:assets.find(a=>a.name===ref.name)?.text||ws.taskCanvas.inputSnapshots?.[ref.name]||'',source:'工作包交付物'}))}catch{return null}}
