 function graphMarkup(){const ts=stageTasks();if(!ts.length)return '<div class="rf-graph-empty">当前子阶段还没有节点。点击“新增节点”开始整理工作流程。</div>';const layout=FlowDraft.layout(ts,data.edges[stage]),columns=layout.columns;const minimum=columns*170+Math.max(0,columns-1)*64;return `<div class="rf-graph-scroll"><div class="rf-graph-canvas ${layout.rows>1?'branch':'linear'}" data-stage-graph="${stage}" style="--columns:${columns};--graph-rows:${layout.rows};--graph-min:${minimum}px"><svg class="rf-edges" aria-label="节点依赖连线"></svg>${ts.map(t=>{const pos=layout.positions[t.id];return `<div role="group" tabindex="0" class="rf-task-node ${selected===t.id?'selected':''}" data-flow-task="${t.id}" style="grid-column:${pos.column};grid-row:${pos.rowStart} / ${pos.rowEnd}"><div class="rf-task-node-top"><span>${safe(t.id)+(t.demo?' · 演示':'')}</span>${statusHTML(taskStatus(t))}</div><strong><span class="rf-node-symbol">${ico(t.taskType==='实验节点'?'flask':t.taskType==='审批节点'?'check':/模拟|计算/.test(t.taskType||'')?'grid':t.taskType==='分析节点'?'flow':t.name.includes('评审')||t.name.includes('决定')||t.name.includes('入选')?'check':t.name.includes('验证')||t.name.includes('测量')?'flask':'file')}</span>${safe(t.name)}</strong>${TaskDialogueModel.markup({name:t.name,taskType:t.taskType,owner:ownerName(t),executionMode:t.executionMode||'human',collaborators:(t.collaboratorIds||[]).map(id=>members.find(m=>m.id===id)?.name).filter(Boolean)})}<span class="rf-task-scope">${safe(scopeLabel(t))}</span><span class="rf-task-output">${t.deliverables.length>1?t.deliverables.length+' 项交付要求':'查看交付要求'} ${ico('chevron')}</span></div>`}).join('')}</div></div>`}
