 function questionsForStage(){if(projectPhase!=='研发')return [];const ids=({S1:['Q1','Q2','Q3','Q7'],S2:['Q1','Q3','Q4','Q7','Q8'],S3:['Q1','Q4','Q7','Q8'],S4:['Q1','Q4','Q7','Q8'],S5:['Q1','Q4','Q5','Q6','Q7'],S6:['Q1','Q6','Q7']})[stage];return data.questions.filter(q=>ids.includes(q.id))}
 function opIds(t){const matches=t.ops.match(/OP\d+/g)||[];if(t.ops.includes('—')&&matches.length>=2){const a=+matches[0].slice(2),b=+matches[1].slice(2);return [...new Set([...Array.from({length:b-a+1},(_,i)=>'OP'+(i+a)),...matches.slice(2)])]}return matches}
 function drawerMarkup(){const t=taskById(selected),hasWorkItems=!!t.workItems?.length;return `<aside class="rf-drawer" role="dialog" aria-modal="false" aria-labelledby="rf-detail-title" tabindex="-1"><header><div><span>${t.stage} · ${t.id}</span><h2 id="rf-detail-title">${safe(t.name)}</h2></div><button class="icon-btn" data-rf="close-detail" aria-label="关闭任务详情">×</button></header><div class="rf-detail-meta">${statusHTML(taskStatus(t))}${ownerControl(t)}<span>人工完成</span></div><p class="rf-detail-scope">适用范围：${safe(t.scope)}</p><div class="rf-detail-primary-actions"><button class="btn rf-node-workspace-entry" data-enter-node-workspace="${safe(t.id)}">${ico('folder')}进入任务工作台</button>${!hasWorkItems&&taskStatus(t)!=='待开始'?`<button class="btn rf-primary rf-complete-node" data-complete-node="${safe(t.id)}" ${taskStatus(t)==='已完成'?'disabled':''}>${ico('check')}${taskStatus(t)==='已完成'?'阶段任务已完成':'完成阶段任务'}</button>`:''}</div>${phaseComplete()&&nextPhase()?'<div class="rf-detail-phase-action"><button class="rf-text-button" data-next-project-phase>进入'+safe(nextPhase())+'</button></div>':''}<div class="rf-detail-tabs" role="tablist" aria-label="任务详情内容">${[['requirements','工作要求'],['deliveries','输入与交付'],['dependencies','依赖与影响'],['assets','节点资产'],['conversations','对话讨论']].map(([v,n])=>`<button role="tab" data-detail-tab="${v}" aria-selected="${detailTab===v}">${n}</button>`).join('')}</div><div class="rf-detail-body">${detailTab==='requirements'?`<h3>工作目的与完成条件</h3><p>${safe(t.condition)}</p>${deliveryChecklist(t)}${hasWorkItems?`<h3>内部 TODO</h3><p>${t.workItems.map(item=>safe(item.id)+' · '+safe(item.name)).join('<br>')}</p>`:''}<h3>职责与完成方式</h3><p>负责人：${safe(ownerName(t))}。人工完成，签核授权需另行核对。</p>${t.id==='T22'?'<div class="rf-detail-callout">4h施工窗内使用合格批料，制板不能机械等待8h观察。最终推进仍须完整 G1 证据。</div>':''}${t.id==='T12'||t.id==='T21'||t.id==='T22'?'<h3>R3层间与分层记录</h3><p>底层和面层分别制备放行，关联到同一体系板。底层处理后，冷却后30min内上面层，再共同最终固化；不能用一层记录替代体系要求。</p>':''}<h3>相关操作 SOP</h3><div class="rf-op-links">${opIds(t).map(id=>{const op=data.ops.find(o=>o.id===id);return `<button data-flow-op="${id}">${ico('file')}<span>${op.title}<small>${op.source}</small></span>${ico('chevron')}</button>`}).join('')}</div>`:detailTab==='deliveries'?deliveryMarkup(t):detailTab==='dependencies'?`<h3>上游输入</h3><p>${safe(t.input)}</p><div class="rf-dependency-links">${dependencies(t.id).map(id=>`<button data-flow-task="${id}">${id} · ${safe(taskById(id).name)}</button>`).join('')||'<p>承接上阶段范围与相关实施条件。准备工作可提前，实物门槛仍需满足。</p>'}</div><h3>当前前置缺口</h3><p>${t.id==='T26'?stageGap():mode==='plan'?'来源为计划定义，实际输入尚未提交或确认；查看要求不等于执行就绪。':t.id==='T24'&&!r3Report?'R3报告尚未提交，影响对应范围的比较证据；其他路线记录可继续整理。':'演示交付不等于结果通过；须逐范围核实来源、版本和条件。'}</p><h3>下游影响</h3><div class="rf-dependency-links">${downstream(t.id).map(id=>`<button data-flow-task="${id}">${id} · ${safe(taskById(id).name)}</button>`).join('')||'<p>影响本阶段推进决定及下阶段实际确认范围。</p>'}</div><div class="rf-detail-callout">${stageData().decision}</div>`:detailTab==='assets'?nodeAssets(t):conversationList(t)}</div><footer><div class="rf-node-edit-actions"><button class="btn" data-rf-editor="edit-node" ${mode!=='plan'||nodeLocked(t)?'disabled title="已完成节点不可修改"':''}>${ico('edit')}修改节点</button><button class="btn rf-danger" data-rf-editor="delete-node" ${mode!=='plan'||nodeLocked(t)?'disabled title="已完成节点及其关联连线不可删除"':''}>删除节点</button></div><span>工作交付 ≠ 结果通过 ≠ 阶段放行</span></footer></aside>`}
 function nodeAssets(t){const records=nodeAssetRecords(t);return `<div class="rf-checklist-heading"><h3>节点资产 <small>${records.length}</small></h3><button class="btn" data-upload-node-asset>${ico('plus')}上传文件</button></div><p class="rf-muted">上传文件或将其他成果登记为交付记录，自动关联交付清单。非文本文件保留名称与关联，文件原件请自行保管。</p><div class="rf-node-assets">${records.map(a=>`<button data-node-asset="${safe(a.id)}">${ico('file')}<span><strong>${safe(a.name)}</strong><small>${safe(a.source||'节点资产')}</small></span>${ico('chevron')}</button>`).join('')||'<p class="rf-muted">暂无节点资产，交付要求不会被当作已交付文件。</p>'}<button data-node-input="${safe(t.id)}">${ico('file')}<span><strong>${safe(t.name)}—任务要求.md</strong><small>查看输入与工作要求 · 不计入交付</small></span>${ico('chevron')}</button></div><button class="rf-text-button" data-register-delivery>登记其他交付物</button>${deliveryChecklist(t)}`}
 function registerDelivery(){const t=taskById(selected);editorShell('登记其他交付物',`<form id="rf-register-delivery"><label>对应交付物<select name="delivery">${requirementsFor(t).map(d=>`<option value="${safe(d.id)}">${safe(d.description)}</option>`).join('')}</select></label><label>成果名称<input name="name" required maxlength="100" placeholder="如：样板批次与归档位置"></label><label>成果说明或存放位置<textarea name="text" required rows="3"></textarea></label><div class="rf-dialog-actions"><button class="btn rf-primary">登记交付物</button></div></form>`);$('#rf-register-delivery').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),key=progressKey(t);(progress.assets[key]||=[]).push({id:'record-'+Date.now().toString(36),name:f.get('name').trim(),text:f.get('text').trim(),deliveryId:f.get('delivery'),source:'人工登记成果'});saveProgress();editorDialog.close();render();toast('交付物已登记')}}
 function conversationList(t){return `<h3>关联的 AI 对话</h3><p class="rf-muted">以下为原型对话示例。点击进入该节点的任务工作区查看对话与资产。</p><div class="rf-conversation-list"><button data-node-conversation="${safe(t.id)}">${ico('spark')}<span><strong>${safe(t.name)} · 材料准备</strong><small>SynMatAI · 已关联当前节点 · 示例对话</small></span>${ico('chevron')}</button></div>`}
 function activateProjectNode(id){const t=canvasNode(id);if(!t)return;const action=WorkspaceNodeOpening.kind(t);if(action==='file')return enterNodeWorkspace(t.producerId,{openAction:'document',fileName:t.name,canvasFile:t});if(action==='experiment')return WorkspaceNodeOpening.experiment(t,{phase:projectPhase,stage});if(action==='approval')return WorkspaceNodeOpening.approval({...t,done:taskStatus(t)==='已完成'},{key:'project/'+projectPhase+'/'+t.id,owner:ownerName(t)});enterNodeWorkspace(id,{openAction:'conversation-assets'})}
 function enterNodeWorkspace(id,options={}){const original=taskById(id);if(!original)return;const t=structuredClone(original),phase=projectPhase,sub=projectPhase==='研发'?researchStageName(t.stage):projectPhase==='量产'?stageData().short:'',assets=nodeAssetRecords(t);if(options.canvasFile&&!assets.some(a=>a.name===options.canvasFile.name))assets.push({id:options.canvasFile.id,name:options.canvasFile.name,text:options.canvasFile.text,source:'画布结果文件'});const detail={phase,sub,node:t,status:taskStatus(t),assets,stageTasks:stageTasks().map(n=>({id:n.id,name:n.name,status:taskStatus(n)})),...options};close({preserveRoute:true});window.ProjectWorkspace?.activate('task');document.body.classList.remove('assets-active','experiments-active','overview-active','projects-active','research-flow-active','flow-canvas-active','flow-v3-active');document.body.classList.add('task-workspace-active');document.dispatchEvent(new CustomEvent('synmat:open-flow-task',{detail}))}

 function deliveryMarkup(t){return `<h3>输入来源</h3><p>${safe(t.input)}</p><h3>交付要求 <small>${t.deliverables.length}项</small></h3><div class="rf-delivery-list">${t.deliverables.map(d=>`<button data-open-delivery="${d.id}"><span class="rf-delivery-icon">${ico('file')}</span><span><strong>${safe(d.description)}</strong><small>${d.id} · ${mode==='plan'?'预期交付 · 版本未生成':'演示记录 · 版本 v0.1'}</small></span>${ico('chevron')}</button>`).join('')}</div>${mode==='simulation'&&t.id==='T24'?`<h3>沸水记录完整性 · 演示</h3><div class="rf-demo-records">${['R1','R2','R3','R4'].map(r=>`<div><strong>${r}</strong><span>${r==='R3'&&!r3Report?'待提交':'已交付 · '+(r==='R3'&&r3Failure?'结果未通过':'结果待确认')}</span><small>${r==='R3'&&!r3Report?'无文件':r3Report&&r==='R3'?'演示文件 v0.1':'部分路线报告 · 演示文件'}</small></div>`).join('')}</div>${!r3Report?'<div class="rf-submit-buttons"><button class="btn rf-primary" data-rf="submit-r3">提交R3演示记录</button><button class="btn" data-rf="submit-r3-failure">提交失败报告（演示）</button></div>':'<div class="rf-detail-callout">R3记录已交付。'+(r3Failure?'报告记录为未通过；该范围仍不能放行。':'完整性已更新；性能判定、比较与入选仍须人工确认。')+'</div>'}`:''}<h3>追溯要求</h3><p>按任务、路线、层/体系、化学版本、工艺版本、前处理、独立批次、板号及时间点索引，关联匹配清漆空白。新版本保留原有失败记录。</p><div class="rf-detail-callout">${mode==='plan'?'当前没有上传文件，以上均为预期交付定义。':'演示文件仅表示交付状态，不是实测证据。'} 可以完成失败报告的提交工作，但阶段放行仍受结果与全部条件约束。</div>`}
 function openTask(id,tab='requirements'){opener=document.activeElement;selected=id;detailVisible=true;detailTab=tab;render();$('.rf-drawer').focus({preventScroll:true})}
 function closeTask(){const id=selected;detailVisible=false;render();const el=page.querySelector(`[data-flow-task="${id}"]`);(el||opener)?.focus({preventScroll:true})}
 const fileDialog=document.createElement('dialog');fileDialog.className='rf-file-dialog';fileDialog.setAttribute('aria-label','流程资料预览');document.body.append(fileDialog);
 function showFile(title,content,notice='来源文档预览'){fileDialog.innerHTML=`<header><div><span>${notice}</span><h2>${safe(title)}</h2></div><button class="icon-btn" data-close-file aria-label="关闭资料预览">×</button></header><article>${content}</article>`;fileDialog.querySelector('[data-close-file]').onclick=()=>fileDialog.close();fileDialog.showModal()}
 function openDelivery(id){const t=taskById(selected),d=t.deliverables.find(d=>d.id===id);showFile(d.description,`<h3>${mode==='plan'?'预期交付，尚无文件':'演示交付说明'}</h3><p>任务：${safe(t.name)}</p><p>版本：${mode==='plan'?'未生成':'v0.1 · 演示文件'}</p><h3>输入与范围</h3><p>${safe(t.input)}</p><p>${safe(t.scope)}</p><h3>交付与完成要求</h3><p>${safe(d.description)}</p><p>${safe(t.condition)}</p><p class="rf-detail-callout">这里展示文件要求，未伪造真实实验记录、签名或可下载的结果文件。</p>`,mode==='plan'?'交付要求 · 尚未提交':'演示文件要求 · 非实验结果')}
 const actionDialog=document.createElement('dialog');actionDialog.className='rf-action-dialog';actionDialog.setAttribute('aria-label','流程审核操作');document.body.append(actionDialog);
 const editorDialog=document.createElement('dialog');editorDialog.className='rf-editor-dialog';editorDialog.setAttribute('aria-labelledby','rf-editor-title');document.body.append(editorDialog);
 function editorShell(title,body){editorDialog.innerHTML=`<header><div><span>当前子阶段 · ${safe(stageData().title)}</span><h2 id="rf-editor-title">${safe(title)}</h2></div><button class="icon-btn" data-editor-close aria-label="关闭流程编辑">×</button></header><div class="rf-editor-content">${body}<p class="rf-editor-error" role="alert" id="rf-editor-error"></p></div>`;editorDialog.querySelector('[data-editor-close]').onclick=()=>editorDialog.close();if(!editorDialog.open)editorDialog.showModal()}
 function editorFailure(error){$('#rf-editor-error').textContent=error.message||String(error)}
 function editorAction(action){if(mode!=='plan')return toast('请在计划审核模式编辑本地草稿');if(action==='add'){if(canvasMode)canvasController.openCreateMenu();else openNodeEditor()};if(action==='edit-node')openNodeEditor(selected);if(action==='delete-node')deleteNodeDialog();if(action==='edges')openEdgeList();if(action==='undo')travelDraft('undo');if(action==='redo')travelDraft('redo');if(action==='restore')restoreDraftDialog()}
 function openNodeEditor(id=null,preselectedIds=[],creation={}){const node=id?taskById(id):null;if(id&&!node)return;if(nodeLocked(node))return toast('已完成节点不可修改');const choices=stageTasks().filter(t=>t.id!==id),before=node?dependencies(id):[...new Set(preselectedIds)].filter(id=>stageTasks().some(t=>t.id===id)),after=node?downstream(id):[];
 const relationField=(name,title,boundary,label,selected,allowCompleted=false)=>`<fieldset class="rf-node-relations"><legend>${title} · 可多选</legend><label><input type="checkbox" name="${name}" value="${boundary}" ${!selected.length&&name==='before'?'checked':''}>${label}</label>${choices.map(t=>`<label><input type="checkbox" name="${name}" value="${safe(t.id)}" ${selected.includes(t.id)?'checked':''} ${nodeLocked(t)&&!allowCompleted?'disabled':''}>${safe(t.name)}${nodeLocked(t)?allowCompleted?'（已完成 · 可作为上游）':'（已完成 · 不可接入）':''}</label>`).join('')}</fieldset>`;
 editorShell(node?'修改节点':'新增节点',`<form id="rf-node-editor-form"><div class="rf-editor-relations">${relationField('before','前置节点','__start','阶段开始',before,true)}${relationField('after','后置节点','__end','阶段结束',after)}</div><label>节点名称<input name="name" aria-label="节点名称" value="${safe(node?.name||creation.type||'')}" maxlength="100" required placeholder="填写具体工作名称"></label>${creation.type?`<p class="rf-muted">任务类型：${safe(creation.type)} · 确认后连接到来源节点</p>`:''}${memberField(node?.ownerId)}<label>适用范围<input name="scope" aria-label="适用范围" value="${safe(node?.scope||stageData().title+' · 范围待确认')}" required></label><label>输入来源<textarea name="input" aria-label="输入来源" rows="2">${safe(node?.input||'项目资料及相关上游记录，具体版本待确认')}</textarea></label><label>工作要求与完成条件<textarea name="condition" aria-label="工作要求与完成条件" rows="3" required>${safe(node?.condition||'核对输入、形成交付并由负责人确认。具体判据待补充。')}</textarea></label><label>预期交付（每行一项）<textarea name="deliverables" aria-label="预期交付" rows="3" required>${safe(node?node.deliverables.map(d=>d.description).join('\n'):'工作记录及待确认问题清单')}</textarea></label><p class="rf-muted">前置节点必选；后置节点可留空，留空时当前节点即为敞口终态节点。已完成节点仅可作为前置节点。</p><div class="rf-dialog-actions"><button type="button" class="btn" data-editor-cancel>取消</button><button class="btn rf-primary">${node?'保存节点':'添加节点'}</button></div></form>`);
 bindMemberPicker();editorDialog.querySelectorAll('.rf-node-relations input').forEach(input=>input.onchange=()=>{const group=[...editorDialog.querySelectorAll(`input[name="${input.name}"]`)];if(input.checked){if(input.value.startsWith('__'))group.filter(x=>x!==input).forEach(x=>x.checked=false);else group.filter(x=>x.value.startsWith('__')).forEach(x=>x.checked=false)}});
 editorDialog.querySelector('[data-editor-cancel]').onclick=()=>editorDialog.close();$('#rf-node-editor-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),name=f.get('name').trim(),lines=f.get('deliverables').split('\n').map(x=>x.trim()).filter(Boolean);if(!name||!lines.length)throw new Error('请填写节点名称和至少一项预期交付。');const predecessors=[...e.target.querySelectorAll('input[name=before]:checked')].map(x=>x.value),successors=[...e.target.querySelectorAll('input[name=after]:checked')].map(x=>x.value);if(!predecessors.length)throw new Error('请选择前置节点或阶段开始。');const next=draftSnapshot(),nid=node?.id||WorkflowNumbering.nextWorkPackageId(next.tasks,{phase:projectPhase,stageId:stage,stage:stageData()}),updated={...node,id:nid,stage,name,ownerId:f.get('ownerId'),role:'',taskType:node?.taskType||creation.type||'临时任务',scope:f.get('scope').trim(),method:'人工',input:f.get('input').trim(),condition:f.get('condition').trim(),deliverables:lines.map((description,i)=>({id:node?.deliverables[i]?.id||nid+'-D'+(i+1),description})),ops:node?.ops||'',custom:node?.custom||!node,edited:!!node};if(node)next.tasks[next.tasks.findIndex(t=>t.id===nid)]=updated;else next.tasks.push(updated);
 if(creation.inputFile){next.canvasFiles[stage].edges.push([creation.inputFile,nid,'文件输入','dependency',{fromPort:creation.fromPort,toPort:'left'}])}const old=next.edges[stage];next.edges[stage]=old.filter(([a,b])=>a!==nid&&b!==nid);for(const from of predecessors.filter(x=>x!=='__start'&&!creation.inputFile))next.edges[stage].push(old.find(([a,b])=>a===from&&b===nid)||[from,nid,'','dependency',creation.fromPort?{fromPort:creation.fromPort,toPort:'left'}:undefined]);for(const to of successors.filter(x=>x!=='__end'))next.edges[stage].push(old.find(([a,b])=>a===nid&&b===to)||[nid,to]);FlowDraft.validate(next);assertUnlockedChanges(next,!node&&preselectedIds.length>0);if(!node&&canvasMode)canvasController?.prepareNewNode(nid,predecessors,successors,creation.position);selected=canvasMode&&!node?null:nid;detailVisible=!(canvasMode&&!node);commitDraft(next,node?'节点已更新':'节点已添加',!node&&preselectedIds.length>0);editorDialog.close();if(canvasMode&&!node)canvasController?.focus(nid);else $('.rf-drawer')?.focus({preventScroll:true})}catch(error){editorFailure(error)}};
 }
 function deleteNodeDialog(ids=[selected]){const tasks=[...new Set(ids)].map(taskById).filter(Boolean),locked=tasks.filter(nodeLocked),removable=tasks.filter(t=>!nodeLocked(t));if(!removable.length)return toast('已完成节点不可删除');const removeIds=new Set(removable.map(t=>t.id)),related=data.edges[stage].filter(([a,b])=>removeIds.has(a)||removeIds.has(b)).length;editorShell('删除节点',`<p>删除以下 ${removable.length} 个节点及其 ${related} 条关联连线？</p><ul>${removable.map(t=>`<li>${safe(t.name)}</li>`).join('')}</ul>${locked.length?`<p class="rf-muted">${locked.length} 个已完成节点将保留，不参与删除。</p>`:''}<p class="rf-muted">不会自动连接上下游，不修改已完成节点的内容。删除后可以撤销。</p><div class="rf-dialog-actions"><button class="btn" data-delete-cancel>保留节点</button><button class="btn rf-danger" data-delete-node>确认删除</button></div>`);editorDialog.querySelector('[data-delete-cancel]').onclick=()=>editorDialog.close();editorDialog.querySelector('[data-delete-node]').onclick=()=>{try{let next=draftSnapshot();for(const t of removable){if(nodeLocked(taskById(t.id)))throw new Error('已完成节点不可删除');next=FlowDraft.removeNode(next,t.id)}FlowDraft.validate(next);assertUnlockedChanges(next,false,true);canvasController?.clearSelection();selected=null;detailVisible=false;commitDraft(next,'节点及关联连线已删除',false,true);editorDialog.close()}catch(error){editorFailure(error)}}}
 function deleteEdgeDialog(index){if(mode!=='plan')return toast('请在计划审核模式删除连线');const edge=data.edges[stage][index];if(!edge)return;if(edgeLocked(edge))return toast('已完成节点的既有连线不可修改；可以从已完成节点新增下游连线');editorShell('删除连线',`<p>${safe(taskById(edge[0]).name)} → ${safe(taskById(edge[1]).name)}</p><p>仅删除此依赖关系，保留任务、文件与完成状态。删除后可撤销。</p><div class="rf-dialog-actions"><button class="btn" data-keep-edge>保留连线</button><button class="btn rf-danger" data-confirm-edge-delete>确认删除连线</button></div>`);editorDialog.querySelector('[data-keep-edge]').onclick=()=>editorDialog.close();editorDialog.querySelector('[data-confirm-edge-delete]').onclick=()=>{try{const next=draftSnapshot();next.edges[stage].splice(index,1);commitDraft(next,'连线已删除',false,true,true);editorDialog.close()}catch(error){editorFailure(error)}}}
