function markdown(text){
 const inline=t=>safe(t).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
 const lines=text.replace(/\r/g,'').split('\n');let out='',i=0;
 const cells=l=>l.trim().replace(/^\||\|$/g,'').split('|').map(c=>c.trim());
 while(i<lines.length){const line=lines[i];if(!line.trim()){i++;continue}
 if(/^```/.test(line)){const code=[];i++;while(i<lines.length&&!/^```/.test(lines[i]))code.push(lines[i++]);i++;out+='<pre><code>'+safe(code.join('\n'))+'</code></pre>';continue}
 if(i+1<lines.length&&line.includes('|')&&/^\s*\|?\s*:?-{3,}/.test(lines[i+1])){const headers=cells(line),align=cells(lines[i+1]);i+=2;let rows='';while(i<lines.length&&lines[i].includes('|')&&lines[i].trim())rows+='<tr>'+cells(lines[i++]).map((c,j)=>`<td${align[j]?.endsWith(':')?' class="numeric"':''}>${inline(c)}</td>`).join('')+'</tr>';out+='<div class="markdown-table-scroll"><table><thead><tr>'+headers.map(c=>'<th>'+inline(c)+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div>';continue}
 const h=line.match(/^(#{1,6})\s+(.+)$/);if(h){out+=`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`;i++;continue}
 if(/^\s*([-*_])(?:\s*\1){2,}\s*$/.test(line)){out+='<hr>';i++;continue}
 if(/^>/.test(line)){out+='<blockquote>'+inline(line.replace(/^>\s?/,''))+'</blockquote>';i++;continue}
 if(/^\s*(?:[-*]|\d+\.)\s+/.test(line)){const ordered=/^\s*\d+\./.test(line),tag=ordered?'ol':'ul';out+='<'+tag+'>';while(i<lines.length&&/^\s*(?:[-*]|\d+\.)\s+/.test(lines[i]))out+='<li>'+inline(lines[i++].replace(/^\s*(?:[-*]|\d+\.)\s+/,''))+'</li>';out+='</'+tag+'>';continue}
 let paragraph=line;i++;while(i<lines.length&&lines[i].trim()&&!/^(?:#{1,6} |```|>|\s*[-*] )/.test(lines[i])&&!(lines[i].includes('|')&&/^\s*\|?\s*:?-{3,}/.test(lines[i+1]||'')))paragraph+='\n'+lines[i++];out+='<p>'+inline(paragraph).replace(/\n/g,'<br>')+'</p>';
 }return out;
}

